
import { useState } from "react";
import {
  BrowserRouter,
    Routes,
      Route,
        Link,
          useNavigate
          } from "react-router-dom";

          function Navbar() {
            return (
                <nav className="navbar">
                      <Link to="/" className="brand">MyMiniSite.</Link>

                            <div className="nav-links">
                                    <Link to="/">Home</Link>
                                            <Link to="/about">About</Link>
                                                    <Link to="/contact">Contact</Link>
                                                          </div>
                                                              </nav>
                                                                );
                                                                }

                                                                function Home() {
                                                                  return (
                                                                      <main className="hero">
                                                                            <span className="tag">BSIT 3RD YEAR • REACT</span>
                                                                                  <h1>Welcome to My Mini Site</h1>
                                                                                        <p>
                                                                                                A simple React website built with React Router,
                                                                                                        reusable components, and a working contact form.
                                                                                                              </p>

                                                                                                                    <div className="actions">
                                                                                                                            <Link className="button primary" to="/about">
                                                                                                                                      Learn More
                                                                                                                                              </Link>
                                                                                                                                                      <Link className="button secondary" to="/contact">
                                                                                                                                                                Contact Me
                                                                                                                                                                        </Link>
                                                                                                                                                                              </div>
                                                                                                                                                                                  </main>
                                                                                                                                                                                    );
                                                                                                                                                                                    }

                                                                                                                                                                                    function About() {
                                                                                                                                                                                      return (
                                                                                                                                                                                          <main className="page-card">
                                                                                                                                                                                                <span className="tag">ABOUT THIS PROJECT</span>
                                                                                                                                                                                                      <h1>About Us</h1>
                                                                                                                                                                                                            <p>
                                                                                                                                                                                                                    My Mini Site is a student project created using React.
                                                                                                                                                                                                                            It demonstrates page navigation, components, controlled
                                                                                                                                                                                                                                    form inputs, and form submission handling.
                                                                                                                                                                                                                                          </p>

                                                                                                                                                                                                                                                <h3>What I Learned</h3>
                                                                                                                                                                                                                                                      <ul>
                                                                                                                                                                                                                                                              <li>Creating reusable React components</li>
                                                                                                                                                                                                                                                                      <li>Using React Router for navigation</li>
                                                                                                                                                                                                                                                                              <li>Managing input values with useState</li>
                                                                                                                                                                                                                                                                                      <li>Validating a form before submission</li>
                                                                                                                                                                                                                                                                                            </ul>

                                                                                                                                                                                                                                                                                                  <Link className="button primary" to="/contact">
                                                                                                                                                                                                                                                                                                          Get in Touch
                                                                                                                                                                                                                                                                                                                </Link>
                                                                                                                                                                                                                                                                                                                    </main>
                                                                                                                                                                                                                                                                                                                      );
                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                      function Contact() {
                                                                                                                                                                                                                                                                                                                        const navigate = useNavigate();

                                                                                                                                                                                                                                                                                                                          const [name, setName] = useState("");
                                                                                                                                                                                                                                                                                                                            const [email, setEmail] = useState("");
                                                                                                                                                                                                                                                                                                                              const [error, setError] = useState("");

                                                                                                                                                                                                                                                                                                                                function handleSubmit(event) {
                                                                                                                                                                                                                                                                                                                                    event.preventDefault();

                                                                                                                                                                                                                                                                                                                                        const cleanName = name.trim();
                                                                                                                                                                                                                                                                                                                                            const cleanEmail = email.trim();

                                                                                                                                                                                                                                                                                                                                                if (!cleanName || !cleanEmail) {
                                                                                                                                                                                                                                                                                                                                                      setError("Please enter both your name and email.");
                                                                                                                                                                                                                                                                                                                                                            return;
                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                    const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

                                                                                                                                                                                                                                                                                                                                                                        if (!emailPattern.test(cleanEmail)) {
                                                                                                                                                                                                                                                                                                                                                                              setError("Please enter a valid email address.");
                                                                                                                                                                                                                                                                                                                                                                                    return;
                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                            setError("");
                                                                                                                                                                                                                                                                                                                                                                                                navigate("/thank-you");
                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                    return (
                                                                                                                                                                                                                                                                                                                                                                                                        <main className="page-card">
                                                                                                                                                                                                                                                                                                                                                                                                              <span className="tag">LET'S CONNECT</span>
                                                                                                                                                                                                                                                                                                                                                                                                                    <h1>Contact Us</h1>
                                                                                                                                                                                                                                                                                                                                                                                                                          <p>Fill out the form below to send your information.</p>

                                                                                                                                                                                                                                                                                                                                                                                                                                <form onSubmit={handleSubmit} noValidate>
                                                                                                                                                                                                                                                                                                                                                                                                                                        <label htmlFor="name">Full Name</label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                <input
                                                                                                                                                                                                                                                                                                                                                                                                                                                          id="name"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    type="text"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              placeholder="Enter your full name"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        value={name}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  onChange={(event) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              setName(event.target.value);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          setError("");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            />

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <label htmlFor="email">Email Address</label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      id="email"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                type="email"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          placeholder="example@email.com"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    value={email}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              onChange={(event) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          setEmail(event.target.value);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      setError("");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        />

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {error && <p className="error-message">{error}</p>}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <button className="button primary submit-button" type="submit">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  Submit Form
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </form>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </main>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      function ThankYou() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <main className="page-card thank-you">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div className="success-icon">✓</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <h1>Thank You!</h1>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <p>Your form was submitted successfully.</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <p>We appreciate you getting in touch.</p>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <Link className="button primary" to="/">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  Back to Home
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </Link>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </main>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              export default function App() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <BrowserRouter>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div className="app">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Navbar />

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <Routes>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <Route path="/" element={<Home />} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <Route path="/about" element={<About />} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <Route path="/contact" element={<Contact />} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Route path="/thank-you" element={<ThankYou />} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </Routes>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <footer>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <p>MyMiniSite © 2026 | React Coding Activity</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </footer>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </BrowserRouter>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                